//! What the storage page shows, decided without touching Slint.
//!
//! This file is mounted into `wsadash` with `#[path]` so its tests run under
//! `cargo test --release --bin wsadash` -- see `src/wsadash.rs`. That is also
//! why it returns plain [`StorageRow`]s and not the `StorageImageUI` struct
//! from `theme.slint`: that one is generated by the Slint compiler and exists
//! only in the GUI binary, so naming it here would make this module impossible
//! to mount into the CLI, and its tests would never compile at all. The
//! conversion happens in `ui/handlers/disk.rs`, exactly as `data::row` turns a
//! `home_model::AppRow` into a `Distro`.
//!
//! The page's whole reason to exist is spec 11 line 348: with the subsystem
//! closed it still has to answer. Everything here is therefore written to
//! return an answer for every input, including the one where the directory is
//! not there at all.

use std::path::Path;

use crate::i18n;
use crate::wsa::app::storage::{self, StorageRole};

/// One row, as this module produces it.
///
/// Plain Rust rather than the `StorageImageUI` struct from `theme.slint`: see
/// the module comment. `ui/handlers/disk.rs` converts.
#[derive(Debug, Clone, PartialEq)]
pub struct StorageRow {
    pub file_name: String,
    pub path: String,
    pub size_text: String,
    pub modified_text: String,
    pub role_text: &'static str,
}

/// Everything the page needs for one render.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct StoragePage {
    pub rows: Vec<StorageRow>,
    /// Appended to the empty state. Empty when there are rows, *and* empty when
    /// there are none but the folder exists -- "WSA is installed and its images
    /// are gone" is a different fact from "there is no WSA data folder here",
    /// and only the second one needs the path spelled out.
    pub note: String,
}

/// Binary units, one decimal, so the number matches what Explorer's properties
/// dialog shows for the same file.
pub fn size_text(bytes: u64) -> String {
    const UNITS: [&str; 5] = ["B", "KB", "MB", "GB", "TB"];
    if bytes < 1024 {
        return format!("{bytes} B");
    }
    let mut value = bytes as f64;
    let mut unit = 0;
    while value >= 1024.0 && unit + 1 < UNITS.len() {
        value /= 1024.0;
        unit += 1;
    }
    // One decimal, and no ".0" trimmed away: "1.0 GB" and "1 GB" read as two
    // different amounts of care to someone comparing against Explorer.
    format!("{:.1} {}", value, UNITS[unit])
}

pub fn role_text(role: StorageRole) -> &'static str {
    match role {
        StorageRole::UserData => "userdata",
        StorageRole::Metadata => "metadata",
    }
}

/// The page for whatever is (or is not) in `dir`.
///
/// Never fails. `None` means the platform gave no `LOCALAPPDATA`; `Some` a
/// directory that may or may not exist -- [`storage::images_in`] already turns
/// a missing one into an empty list, which is the behaviour this page wants.
pub fn model(dir: Option<&Path>) -> StoragePage {
    let rows = match dir {
        Some(dir) => match storage::images_in(dir) {
            Ok(images) => images
                .into_iter()
                .map(|image| StorageRow {
                    file_name: image.file_name,
                    path: image.path.to_string_lossy().into_owned(),
                    size_text: size_text(image.size_bytes),
                    modified_text: image.modified,
                    role_text: role_text(image.role),
                })
                .collect(),
            // A folder we cannot even list is not a reason to leave the page
            // blank; it is a folder worth naming in the empty state.
            Err(_) => Vec::new(),
        },
        None => Vec::new(),
    };

    // A populated page needs no note; an empty one always needs a sentence. The
    // two empty cases are worded apart because they are different facts: a
    // folder that is there and holds nothing means WSA was reset or moved, and
    // a folder that could not be located means this account has never had it.
    let note = if rows.is_empty() {
        match dir {
            Some(dir) => format!("{} {}", i18n::t("mount_disk.no_mounted"), dir.display()),
            None => i18n::t("mount_disk.no_mounted_no_dir"),
        }
    } else {
        String::new()
    };

    StoragePage { rows, note }
}

/// The argument to hand `open::that` when the caller means *open this folder*.
///
/// Two functions rather than one that asks `path.is_dir()`: that question has
/// no good answer on the machine this page exists for. `LocalCache` is absent
/// whenever WSA has never run -- which is the state spec 11 line 348 is about
/// -- and a guess would then add `/select,` to a path Explorer cannot select,
/// so "Open Folder" would report an error instead of opening anything. The
/// caller knows what it meant; the filesystem does not.
pub fn explorer_arg_for_dir(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}

/// The argument to hand `open::that` when the caller means *show me this file*.
pub fn explorer_arg_for_file(path: &Path) -> String {
    format!("/select,{}", path.display())
}

#[cfg(test)]
mod tests {
    use super::{explorer_arg_for_dir, explorer_arg_for_file, model, role_text, size_text};
    use crate::wsa::app::storage::StorageRole;

    /// Binary units with one decimal, because that is what Explorer's
    /// properties dialog shows for the same file. A reader comparing the two
    /// should not have to do arithmetic, and a page whose content is "how much
    /// space is left" cannot afford to be off by 2^30 from a familiar number.
    #[test]
    fn sizes_are_binary_with_one_decimal() {
        assert_eq!(size_text(0), "0 B");
        assert_eq!(size_text(1023), "1023 B");
        assert_eq!(size_text(1024), "1.0 KB");
        // 2,995,781,632 bytes -- the real `userdata.2.vhdx` on this machine.
        assert_eq!(size_text(2_995_781_632), "2.8 GB");
        assert_eq!(size_text(75_497_472), "72.0 MB");
    }

    #[test]
    fn the_two_roles_get_the_two_labels_the_card_branches_on() {
        assert_eq!(role_text(StorageRole::UserData), "userdata");
        assert_eq!(role_text(StorageRole::Metadata), "metadata");
    }

    /// The state spec 11 line 348 is about: the subsystem is not running, and
    /// very often the data folder is not there either. The answer has to be a
    /// page, not an error, and it has to say *why* it found nothing.
    #[test]
    fn a_missing_directory_is_an_empty_page_that_explains_itself() {
        let page = model(None);
        assert!(page.rows.is_empty(), "{:?}", page.rows);
        assert!(!page.note.is_empty(), "the empty state must say something");
        assert!(
            page.note.contains("LOCALAPPDATA"),
            "with no folder to name, the note must name what it needed: {}",
            page.note
        );
    }

    /// A directory that exists but holds no images is the *more* common empty
    /// state -- a WSA reset, or a subscription that reinstalled under a new
    /// package family -- and it gets the folder it looked in, because that is
    /// the fact worth checking. An empty string here was the first version's
    /// answer, and it left the empty state rendering its icon over nothing.
    #[test]
    fn a_directory_with_no_images_names_the_directory_it_searched() {
        let dir = tempfile::tempdir().unwrap();
        let page = model(Some(dir.path()));
        assert!(page.rows.is_empty());
        assert!(
            page.note.contains(&dir.path().to_string_lossy().to_string()),
            "the note must carry the folder: {}",
            page.note
        );
    }

    /// Two callers, two intents, one callback. The card passes a file and
    /// expects Explorer to *select* it; the bottom bar passes the folder and
    /// expects Explorer to *open* it.
    ///
    /// Neither path exists here, deliberately: `LocalCache` is absent on any
    /// machine where WSA has never run, which is the state this page is for. A
    /// single function that asked the filesystem which it was would answer
    /// "file" for the folder and hand Explorer a `/select,` it cannot satisfy.
    #[test]
    fn the_explorer_argument_is_decided_by_the_caller_not_by_the_filesystem() {
        let dir = std::path::Path::new(r"C:\cache");
        let file = std::path::Path::new(r"C:\cache\userdata.2.vhdx");
        assert_eq!(explorer_arg_for_dir(dir), dir.to_string_lossy());
        assert_eq!(explorer_arg_for_file(file), format!("/select,{}", file.display()));
    }

    /// A file that was deleted between the last refresh and the click still
    /// produces something `open::that` will not choke on.
    #[test]
    fn an_explorer_argument_is_produced_for_a_path_that_does_not_exist() {
        let gone = std::path::Path::new(r"C:\cache\userdata.2.vhdx");
        assert!(!explorer_arg_for_file(gone).is_empty());
    }

    /// The whole loop on this side of the boundary: read two images, and the
    /// page comes back with both, the big one first, each carrying a size the
    /// user can read.
    #[test]
    fn the_page_lists_both_images_with_the_data_one_first() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("metadata.2.vhdx"), vec![0u8; 4096]).unwrap();
        std::fs::write(dir.path().join("userdata.2.vhdx"), vec![0u8; 8192]).unwrap();

        let page = model(Some(dir.path()));
        assert_eq!(page.rows.len(), 2, "{:?}", page.rows);
        assert_eq!(page.rows[0].role_text, "userdata");
        assert_eq!(page.rows[0].size_text, "8.0 KB");
        assert_eq!(page.rows[1].role_text, "metadata");
        assert_eq!(page.rows[1].size_text, "4.0 KB");
        assert!(page.note.is_empty(), "a populated page needs no note");
        assert!(
            page.rows[0].path.ends_with("userdata.2.vhdx"),
            "{}",
            page.rows[0].path
        );
    }
}
